func newServiceFailure() unsafe.Pointer { return unsafe.Pointer(new(servicefailure.ServiceFailure)) }

func newNServiceFailure(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]servicefailure.ServiceFailure, n)))
}

func ptrServiceFailure(p unsafe.Pointer, c int32) any {
	r := (*servicefailure.ServiceFailure)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.ShipmentMoveID))
	case 5:
		return (*string)(unsafe.Pointer(&r.StopID))
	case 6:
		return (**string)(unsafe.Pointer(&r.ReasonCodeID))
	case 7:
		return &r.Number
	case 8:
		return (*string)(unsafe.Pointer(&r.Type))
	case 9:
		return (*string)(unsafe.Pointer(&r.Source))
	case 10:
		return (*string)(unsafe.Pointer(&r.Status))
	case 11:
		return (*string)(unsafe.Pointer(&r.StopType))
	case 12:
		return &r.ScheduledCutoff
	case 13:
		return &r.ActualArrival
	case 14:
		return (*int64)(unsafe.Pointer(&r.GracePeriodMinutes))
	case 15:
		return &r.LateMinutes
	case 16:
		return &r.Notes
	case 17:
		return &r.InternalNotes
	case 18:
		return &r.X12StatusCodeOverride
	case 19:
		return &r.X12ReasonCodeOverride
	case 20:
		return &r.X12ExceptionCode
	case 21:
		return &r.DetectedAt
	case 22:
		return &r.ReviewedAt
	case 23:
		return (**string)(unsafe.Pointer(&r.ReviewedByID))
	case 24:
		return &r.ResolvedAt
	case 25:
		return (**string)(unsafe.Pointer(&r.ResolvedByID))
	case 26:
		return &r.VoidedAt
	case 27:
		return (**string)(unsafe.Pointer(&r.VoidedByID))
	case 28:
		return &r.VoidReason
	case 29:
		return (**string)(unsafe.Pointer(&r.CreatedByID))
	case 30:
		return &r.Version
	case 31:
		return &r.CreatedAt
	case 32:
		return &r.UpdatedAt
	case 33:
		return &r.SearchVector
	case 34:
		return (*string)(unsafe.Pointer(&r.LocationID))
	}
	return nil
}

func valueServiceFailure(p unsafe.Pointer, c int32) any {
	r := (*servicefailure.ServiceFailure)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.ShipmentMoveID)
	case 5:
		return string(r.StopID)
	case 6:
		if r.ReasonCodeID == nil {
			return nil
		}
		return string(*r.ReasonCodeID)
	case 7:
		return r.Number
	case 8:
		return string(r.Type)
	case 9:
		return string(r.Source)
	case 10:
		return string(r.Status)
	case 11:
		return string(r.StopType)
	case 12:
		return r.ScheduledCutoff
	case 13:
		return r.ActualArrival
	case 14:
		return int64(r.GracePeriodMinutes)
	case 15:
		return r.LateMinutes
	case 16:
		if r.Notes == "" {
			return nil
		}
		return r.Notes
	case 17:
		if r.InternalNotes == "" {
			return nil
		}
		return r.InternalNotes
	case 18:
		if r.X12StatusCodeOverride == "" {
			return nil
		}
		return r.X12StatusCodeOverride
	case 19:
		if r.X12ReasonCodeOverride == "" {
			return nil
		}
		return r.X12ReasonCodeOverride
	case 20:
		if r.X12ExceptionCode == "" {
			return nil
		}
		return r.X12ExceptionCode
	case 21:
		return r.DetectedAt
	case 22:
		if r.ReviewedAt == nil {
			return nil
		}
		return *r.ReviewedAt
	case 23:
		if r.ReviewedByID == nil {
			return nil
		}
		return string(*r.ReviewedByID)
	case 24:
		if r.ResolvedAt == nil {
			return nil
		}
		return *r.ResolvedAt
	case 25:
		if r.ResolvedByID == nil {
			return nil
		}
		return string(*r.ResolvedByID)
	case 26:
		if r.VoidedAt == nil {
			return nil
		}
		return *r.VoidedAt
	case 27:
		if r.VoidedByID == nil {
			return nil
		}
		return string(*r.VoidedByID)
	case 28:
		if r.VoidReason == "" {
			return nil
		}
		return r.VoidReason
	case 29:
		if r.CreatedByID == nil {
			return nil
		}
		return string(*r.CreatedByID)
	case 30:
		return r.Version
	case 31:
		return r.CreatedAt
	case 32:
		return r.UpdatedAt
	case 33:
		return r.SearchVector
	case 34:
		return string(r.LocationID)
	}
	return nil
}

func attachServiceFailure(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*servicefailure.ServiceFailure)(p)
	switch rel {
	case 0:
		r.ReasonCode = (*servicefailure.ReasonCode)(child)
	case 1:
		r.Shipment = (*shipment.Shipment)(child)
	case 2:
		r.ShipmentMove = (*shipment.ShipmentMove)(child)
	case 3:
		r.Stop = (*shipment.Stop)(child)
	case 4:
		r.CreatedBy = (*tenant.User)(child)
	case 5:
		r.ReviewedBy = (*tenant.User)(child)
	case 6:
		r.ResolvedBy = (*tenant.User)(child)
	case 7:
		r.VoidedBy = (*tenant.User)(child)
	}
}

func beforeCreateServiceFailure(ctx context.Context, p unsafe.Pointer) error {
	return (*servicefailure.ServiceFailure)(p).BeforeCreate(ctx)
}

func beforeUpdateServiceFailure(ctx context.Context, p unsafe.Pointer) error {
	return (*servicefailure.ServiceFailure)(p).BeforeUpdate(ctx)
}

