	reasonCodesTable.Relations[0].Target = tenantdb.UsersSchema()
	reasonCodesTable.Relations[1].Target = tenantdb.UsersSchema()
	serviceFailuresTable.Relations[0].Target = ReasonCodesSchema()
	serviceFailuresTable.Relations[1].Target = shipmentdb.ShipmentsSchema()
